import type { ColumnDef, DbObject } from "../model";

/**
 * DDL do Oracle a partir do modelo do designer. O Oracle altera a tabela no lugar (`ALTER TABLE`). A numeração automática é a
 * identidade (`GENERATED BY DEFAULT AS IDENTITY`, 12c em diante) nas colunas novas; numa coluna que já existe o servidor não a aceita
 * (`ORA-30673`), então ela vira uma sequência própria com `DEFAULT seq.NEXTVAL` (também de 12c em diante).
 */

export const ORACLE_TYPES = [
  "binary_double", "binary_float", "blob", "char", "clob", "date", "float", "interval day to second", "interval year to month", "nchar", "nclob",
  "number", "nvarchar2", "raw", "timestamp", "timestamp with local time zone", "timestamp with time zone", "varchar2",
];

/** Os tipos que aceitam numeração automática. */
const AUTO_TYPES = new Set(["number", "integer", "int", "smallint"]);
export const isAutoType = (type: string) => AUTO_TYPES.has(type.trim().toLowerCase());

/** Entre aspas duplas, como o Oracle quer os nomes que guardam maiúsculas e minúsculas. */
export const q = (name: string) => `"${name.replace(/"/g, '""')}"`;

/** O tipo como o `CREATE TABLE` o escreve. */
export function oracleColumnType(c: ColumnDef): string {
  const t = c.type.trim().toLowerCase();
  const frac = c.length > 0 ? c.length : c.decimal;
  if (["varchar2", "nvarchar2"].includes(t)) return `${t.toUpperCase()}(${c.length > 0 ? c.length : 255})`;
  if (["char", "nchar"].includes(t)) return `${t.toUpperCase()}(${c.length > 0 ? c.length : 1})`;
  if (t === "raw") return `RAW(${c.length > 0 ? c.length : 16})`;
  if (t === "number" || t === "numeric" || t === "decimal") {
    if (c.length > 0) return c.decimal > 0 ? `NUMBER(${c.length},${c.decimal})` : `NUMBER(${c.length})`;
    return c.decimal > 0 ? `NUMBER(*,${c.decimal})` : "NUMBER";
  }
  if (t === "float") return c.length > 0 && c.length !== 126 ? `FLOAT(${c.length})` : "FLOAT";
  if (t.startsWith("timestamp")) {
    const zone = t.slice("timestamp".length).trim().toUpperCase();
    return `TIMESTAMP${frac > 0 ? `(${frac})` : ""}${zone ? ` ${zone}` : ""}`;
  }
  return t.toUpperCase();
}

const fieldList = (fields: string) => fields.split(",").map((f) => q(f.trim().replace(/^"|"$/g, ""))).filter((f) => f !== '""').join(", ");

function columnLine(c: ColumnDef): string {
  const line = `${q(c.name)} ${oracleColumnType(c)}`;
  // A identidade já é obrigatória e não aceita valor padrão.
  if (c.autoInc) return `${line} GENERATED BY DEFAULT AS IDENTITY`;
  return `${line}${c.default ? ` DEFAULT ${c.default}` : ""}${c.notNull || c.key ? " NOT NULL" : ""}`;
}

function fkLine(f: NonNullable<DbObject["foreignKeys"]>[number]): string {
  const ref = `${f.refSchema ? `${q(f.refSchema)}.` : ""}${q(f.refTable)}`;
  const refs = f.refFields.trim() ? ` (${fieldList(f.refFields)})` : "";
  let line = `${f.name ? `CONSTRAINT ${q(f.name)} ` : ""}FOREIGN KEY (${fieldList(f.fields)}) REFERENCES ${ref}${refs}`;
  // O Oracle só tem `ON DELETE` (CASCADE e SET NULL); `NO ACTION` é o padrão e `ON UPDATE` não existe.
  if (f.onDelete === "CASCADE" || f.onDelete === "SET NULL") line += ` ON DELETE ${f.onDelete}`;
  return line;
}

function constraintLines(t: DbObject, name: string): string[] {
  const out: string[] = [];
  const keys = (t.columns ?? []).filter((c) => c.key).sort((a, b) => (a.key ?? 0) - (b.key ?? 0));
  if (keys.length) out.push(`CONSTRAINT ${q(`PK_${name}`)} PRIMARY KEY (${keys.map((k) => q(k.name)).join(", ")})`);
  for (const u of t.uniques ?? []) if (fieldList(u.fields)) out.push(`${u.name ? `CONSTRAINT ${q(u.name)} ` : ""}UNIQUE (${fieldList(u.fields)})`);
  for (const c of t.checks ?? []) if (c.expression.trim()) out.push(`${c.name ? `CONSTRAINT ${q(c.name)} ` : ""}CHECK (${c.expression.trim()})`);
  for (const f of t.foreignKeys ?? []) if (fieldList(f.fields) && f.refTable) out.push(fkLine(f));
  return out;
}

const indexSql = (schema: string, target: string, i: { name: string; fields: string; unique: boolean }) =>
  `CREATE ${i.unique ? "UNIQUE " : ""}INDEX ${q(schema)}.${q(i.name)} ON ${target} (${fieldList(i.fields)})`;

export function createTableStatementsOracle(schema: string, table: DbObject, nameOverride?: string): string[] {
  const name = nameOverride ?? table.name;
  const target = `${q(schema)}.${q(name)}`;
  const lines = [...(table.columns ?? []).map(columnLine), ...constraintLines(table, name)];
  const out = [`CREATE TABLE ${target} (\n  ${lines.join(",\n  ")}\n)`];
  for (const i of table.indexes ?? []) if (i.name && fieldList(i.fields)) out.push(indexSql(schema, target, i));
  return out;
}

/** Criar a view; ao alterar, `CREATE OR REPLACE`. */
export function viewStatementsOracle(schema: string, name: string, definition: string, replace: boolean): string[] {
  return [`CREATE ${replace ? "OR REPLACE " : ""}VIEW ${q(schema)}.${q(name)} AS\n${definition.trim().replace(/;+\s*$/, "")}`];
}

/** Nome da sequência que numera uma coluna que já existia. */
export const sequenceName = (table: string, column: string) => `${table}_${column}_SEQ`.slice(0, 128);

/** Cria a sequência começando depois do maior valor da coluna (um bloco PL/SQL: o valor inicial só se sabe no servidor). */
const createSequenceBlock = (schema: string, table: string, column: string, seq: string) =>
  `DECLARE m NUMBER; BEGIN SELECT NVL(MAX(${q(column)}), 0) + 1 INTO m FROM ${q(schema)}.${q(table)}; EXECUTE IMMEDIATE 'CREATE SEQUENCE ${q(schema).replace(/'/g, "''")}.${q(seq).replace(/'/g, "''")} START WITH ' || m; END;`;

export interface OracleAlterPlan { sql: string; statements: string[]; destructive: boolean; notes: string[] }

const sameType = (a: ColumnDef, b: ColumnDef) => oracleColumnType(a) === oracleColumnType(b);
const same = (a?: string, b?: string) => (a ?? "").trim() === (b ?? "").trim();
/** O texto de um comando para mostrar: blocos PL/SQL já terminam em `;`. */
const shown = (s: string) => (s.trimEnd().endsWith(";") ? s : `${s};`);

/**
 * Comandos para levar `original` ao que o designer montou em `next`. `origNames[i]` é o nome que a coluna `i` de `next` tinha ao
 * abrir (vazio = coluna nova).
 */
export function alterStatementsOracle(schema: string, original: DbObject, next: DbObject, origNames: (string | undefined)[]): OracleAlterPlan {
  const table = original.name;
  const target = `${q(schema)}.${q(table)}`;
  const oldCols = original.columns ?? [];
  const newCols = next.columns ?? [];
  const out: string[] = [];
  let destructive = false;
  const kept = new Set(origNames.filter(Boolean));

  // Chave primária: se mudou, cai antes das colunas mudarem e volta depois.
  const oldKey = oldCols.filter((c) => c.key).sort((a, b) => (a.key ?? 0) - (b.key ?? 0)).map((c) => c.name);
  const newKeyOrig = newCols.map((c, i) => ({ c, n: origNames[i] ?? c.name })).filter((x) => x.c.key).sort((a, b) => (a.c.key ?? 0) - (b.c.key ?? 0)).map((x) => x.n);
  const newKeyNow = newCols.filter((c) => c.key).sort((a, b) => (a.key ?? 0) - (b.key ?? 0)).map((c) => c.name);
  const pkChanged = JSON.stringify(oldKey) !== JSON.stringify(newKeyOrig);
  if (pkChanged && oldKey.length) out.push(`ALTER TABLE ${target} DROP PRIMARY KEY`);

  // Colunas que saem (e a sequência que as numerava).
  for (const o of oldCols) {
    if (kept.has(o.name)) continue;
    out.push(`ALTER TABLE ${target} DROP COLUMN ${q(o.name)}`);
    if (o.autoSource) out.push(`DROP SEQUENCE ${seqRef(schema, o.autoSource)}`);
    destructive = true;
  }
  newCols.forEach((c, i) => {
    const from = origNames[i];
    const o = oldCols.find((x) => x.name === from);
    if (!o) {
      out.push(`ALTER TABLE ${target} ADD (${columnLine(c)})`);
      return;
    }
    let name = o.name;
    if (o.name !== c.name) {
      out.push(`ALTER TABLE ${target} RENAME COLUMN ${q(o.name)} TO ${q(c.name)}`);
      name = c.name;
    }
    const wasAuto = !!o.identity;
    const parts: string[] = [];
    if (!sameType(o, c)) {
      parts.push(oracleColumnType(c));
      destructive = true;
    }
    if (!c.autoInc && !wasAuto && !same(o.default, c.default)) parts.push(`DEFAULT ${c.default?.trim() ? c.default.trim() : "NULL"}`);
    // O Oracle recusa `NULL` numa coluna que já aceita nulo (e `NOT NULL` numa que já é obrigatória): só vai o que mudou.
    const wasRequired = !!o.notNull || !!o.key;
    const isRequired = !!c.notNull || !!c.key || !!c.autoInc;
    if (wasRequired !== isRequired) parts.push(isRequired ? "NOT NULL" : "NULL");
    if (parts.length) out.push(`ALTER TABLE ${target} MODIFY (${q(name)} ${parts.join(" ")})`);

    if (wasAuto && !c.autoInc) {
      if (o.autoSource) out.push(`ALTER TABLE ${target} MODIFY (${q(name)} DEFAULT NULL)`, `DROP SEQUENCE ${seqRef(schema, o.autoSource)}`);
      else out.push(`ALTER TABLE ${target} MODIFY (${q(name)} DROP IDENTITY)`);
    } else if (!wasAuto && c.autoInc) {
      const seq = sequenceName(table, name);
      out.push(createSequenceBlock(schema, table, name, seq), `ALTER TABLE ${target} MODIFY (${q(name)} DEFAULT ${q(schema)}.${q(seq)}.NEXTVAL)`);
    }
  });
  if (pkChanged && newKeyNow.length) out.push(`ALTER TABLE ${target} ADD CONSTRAINT ${q(`PK_${table}`)} PRIMARY KEY (${newKeyNow.map(q).join(", ")})`);

  // Restrições e índices, por nome.
  const byName = <T extends { name: string }>(l: T[] | undefined) => new Map((l ?? []).map((x) => [x.name, x]));
  const diff = <T extends { name: string }>(a: T[] | undefined, b: T[] | undefined, key: (x: T) => string, drop: (x: T) => string, add: (x: T) => string | null) => {
    const before = byName(a);
    const after = byName(b);
    for (const [n, x] of before) {
      const y = after.get(n);
      if (!y || key(x) !== key(y)) out.push(drop(x));
    }
    for (const [n, y] of after) {
      const x = before.get(n);
      if (!x || key(x) !== key(y)) {
        const sql = add(y);
        if (sql) out.push(sql);
      }
    }
  };
  const dropConstraint = (x: { name: string }) => `ALTER TABLE ${target} DROP CONSTRAINT ${q(x.name)}`;
  diff(original.foreignKeys, next.foreignKeys, (f) => `${f.fields}|${f.refSchema}|${f.refTable}|${f.refFields}|${f.onDelete}`, dropConstraint,
    (f) => (fieldList(f.fields) && f.refTable ? `ALTER TABLE ${target} ADD ${fkLine(f)}` : null));
  diff(original.uniques, next.uniques, (u) => u.fields.replace(/\s+/g, ""), dropConstraint, (u) => (fieldList(u.fields) ? `ALTER TABLE ${target} ADD ${u.name ? `CONSTRAINT ${q(u.name)} ` : ""}UNIQUE (${fieldList(u.fields)})` : null));
  diff(original.checks, next.checks, (c) => c.expression.trim(), dropConstraint, (c) => (c.expression.trim() ? `ALTER TABLE ${target} ADD ${c.name ? `CONSTRAINT ${q(c.name)} ` : ""}CHECK (${c.expression.trim()})` : null));
  // Os índices que sustentam a chave primária e as restrições UNIQUE aparecem como restrições, não como índices.
  const userIndexes = (original.indexes ?? []).filter((i) => !i.primary && !(original.uniques ?? []).some((u) => u.name === i.name));
  diff(userIndexes, next.indexes, (i) => `${i.fields.replace(/\s+/g, "")}|${i.unique}`, (i) => `DROP INDEX ${q(schema)}.${q(i.name)}`, (i) => (i.name && fieldList(i.fields) ? indexSql(schema, target, i) : null));

  return { sql: out.map(shown).join("\n"), statements: out, destructive, notes: [] };
}

/** `autoSource` guarda o nome da sequência com ou sem o schema; devolve a referência completa. */
const seqRef = (schema: string, source: string) => (source.includes(".") ? source.split(".").map((p) => q(p.replace(/^"|"$/g, ""))).join(".") : `${q(schema)}.${q(source)}`);
